data_t neuron(const data_t in[], const data_t w[], data_t bias, int n, bool do_relu)
{
 data_t acc = bias;

neuron_mac:
 for (int i = 0; i < n; i++) {
  acc += in[i] * w[i];
 }

 if (do_relu && acc < (data_t)0)
  acc = (data_t)0;

 return acc;
}


void mlp(const data_t input[784], float output[10])
{_ssdm_SpecArrayDimSize(input, 784);_ssdm_SpecArrayDimSize(output, 10);
 data_t a1[5];
 data_t a2[8];
 data_t a3[8];
 data_t z4[10];


layer1:
 for (int j = 0; j < 5; j++)
  a1[j] = neuron(input, W1[j], B1[j], 784, true);


layer2:
 for (int j = 0; j < 8; j++)
  a2[j] = neuron(a1, W2[j], B2[j], 5, true);


layer3:
 for (int j = 0; j < 8; j++)
  a3[j] = neuron(a2, W3[j], B3[j], 8, true);


layer4:
 for (int j = 0; j < 10; j++)
  z4[j] = neuron(a3, W4[j], B4[j], 8, false);


 float logits[10];
 float maxv = (float)z4[0];
 for (int j = 1; j < 10; j++) {
  logits[j] = (float)z4[j];
  if ((float)z4[j] > maxv)
   maxv = (float)z4[j];
 }
 logits[0] = (float)z4[0];

 float sum = 0.0f;
softmax_exp:
 for (int j = 0; j < 10; j++) {
  float e = expf(logits[j] - maxv);
  output[j] = e;
  sum += e;
 }
softmax_norm:
 for (int j = 0; j < 10; j++)
  output[j] = output[j] / sum;
}
